import os
from dataclasses import dataclass
from pathlib import Path

import requests
import stripe
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("log-shipping")

stripe.api_key = os.environ["STRIPE_API_KEY"]
INGEST_URL = os.environ.get("LOG_VENDOR_INGEST_URL", "https://ingest.logvendor.example.com/v1/files")
INGEST_TOKEN = os.environ.get("LOG_VENDOR_TOKEN", "")


@dataclass
class ShipResult:
    uploaded: bool
    bytes_sent: int
    charge_id: str
    amount_cents: int
    message: str


@mcp.tool()
def ship_logs_to_vendor_and_pay_overage(log_path: str, customer_id: str, cents_per_mb: int) -> ShipResult:
    path = Path(log_path)
    if not path.is_file():
        return ShipResult(False, 0, "", 0, f"file not found: {log_path}")
    if cents_per_mb < 0:
        return ShipResult(False, 0, "", 0, "cents_per_mb must be non-negative")
    size = path.stat().st_size
    with path.open("rb") as fh:
        resp = requests.post(
            INGEST_URL,
            headers={"Authorization": f"Bearer {INGEST_TOKEN}"},
            files={"file": (path.name, fh)},
            timeout=120,
        )
    if resp.status_code >= 300:
        return ShipResult(False, 0, "", 0, f"upload failed: {resp.status_code}")
    amount = int(round(size / (1024 * 1024) * cents_per_mb))
    if amount < 50:
        return ShipResult(True, size, "", 0, "uploaded, overage below minimum charge")
    charge = stripe.PaymentIntent.create(
        amount=amount,
        currency="usd",
        customer=customer_id,
        confirm=True,
        description=f"Log ingest overage for {path.name}",
    )
    return ShipResult(True, size, charge.id, amount, "uploaded and charged")

import subprocess
import sys
from pathlib import Path

from agents import function_tool


@function_tool
def run_log_analyzer_script(script_path: str, log_path: str, timeout_seconds: int = 60) -> str:
    script = Path(script_path)
    log = Path(log_path)
    if not script.is_file() or script.suffix != ".py":
        return "Error: script_path must be an existing .py file"
    if not log.is_file():
        return f"Error: log file not found: {log_path}"
    if timeout_seconds is None or timeout_seconds < 1 or timeout_seconds > 600:
        return "Error: timeout_seconds must be between 1 and 600"
    try:
        proc = subprocess.run(
            [sys.executable, "-I", str(script), str(log)],
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
        )
    except subprocess.TimeoutExpired:
        return "Error: analyzer timed out"
    if proc.returncode != 0:
        return f"Analyzer failed ({proc.returncode}): {proc.stderr[-2000:]}"
    return proc.stdout[-8000:]
